fun captureCardSourceDirectionForSession(): BiliPaiNavCardSourceDirection {
    return resolveBiliPaiNavCardSourceDirection(
        clickedBoundsRecorded = CardPositionManager.lastClickedCardBounds != null,
        cardFullyVisible = CardPositionManager.isCardFullyVisible,
        isSingleColumnCard = CardPositionManager.isSingleColumnCard,
        normalizedCenterX = CardPositionManager.lastClickedCardCenter?.x
    )
}

prearmVideoCardOpening.originalBody:
fun prearmVideoCardOpening(session: VideoCardTransitionSession) {
    val transitionEnabledForSource = resolveVideoCardTransitionEnabledForSource(
        cardTransitionEnabled = sharedVideoCardTransitionEnabled,
        relatedVideoTransitionEnabled = relatedVideoTransitionEnabled,
        sourceRoute = session.sourceRoute,
    )
    val hasUsableSourceBounds = session.cardBounds
        ?.let { it.width > 1f && it.height > 1f } == true
    if (
        shouldUseMiuixVideoCardMorph(
            cardTransitionEnabled = transitionEnabledForSource,
            reduceMotion = systemReduceMotion,
            sourceRoute = session.sourceRoute,
            hasUsableSourceBounds = hasUsableSourceBounds,
        )
    ) {
        // Activate the source-cover session before NavDisplay mounts the destination.
        // Waiting for its stack-observer effect exposes the black player Surface for one frame.
        videoCardTransitionClock.beginOpeningIfNeeded(session.sourceRoute)
    }
}

resolveVideoCardSourceRouteForNavigation.originalBody:
internal fun resolveVideoCardSourceRouteForNavigation(
    currentRoute: String?,
    videoBvid: String,
    lastClickedVideoSourceKey: String?,
    visibleBottomBarRoutes: Set<String>
): String? {
    if (videoBvid.isBlank() || lastClickedVideoSourceKey.isNullOrBlank()) return null
    val routeBase = normalizeVideoCardNavigationSourceRoute(currentRoute)
    val currentRouteMatch = routeBase
        ?.takeIf { route -> lastClickedVideoSourceKey == "$route:$videoBvid" }
    if (currentRouteMatch != null) return currentRouteMatch

    // Bottom-bar tabs first (MainHost top is not the card host).
    visibleBottomBarRoutes.firstOrNull { route ->
        lastClickedVideoSourceKey == "$route:$videoBvid"
    }?.let { return it }

    // Search / Space / History / video-related / collection hosts are not bottom-bar routes.
    // Still honor the recorded card key so predictive-back sharedBounds land on the same route.
    return resolveClickedVideoSourceRoute(lastClickedVideoSourceKey, videoBvid)
}

normalizeVideoCardNavigationSourceRoute.originalBody:
private fun normalizeVideoCardNavigationSourceRoute(route: String?): String? {
    val normalized = route?.trim()?.takeIf { it.isNotBlank() } ?: return null
    return if (normalized.startsWith("home?category=")) {
        ScreenRoutes.Home.route
    } else {
        normalized.substringBefore("?")
    }
}

resolveClickedVideoSourceRoute.originalBody:
private fun resolveClickedVideoSourceRoute(
    lastClickedVideoSourceKey: String,
    videoBvid: String
): String? {
    val expectedSuffix = ":$videoBvid"
    return lastClickedVideoSourceKey
        .takeIf { it.endsWith(expectedSuffix) }
        ?.removeSuffix(expectedSuffix)
        ?.takeIf { it.isNotBlank() }
}
